INSERT INTO `faqs` (`id`, `question`, `answer`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Apa itu Jasa Website Tangerang?', '<p>\r\n<h3 data-start=\"485\" data-end=\"543\"></h3></p><p data-start=\"273\" data-end=\"483\">Jasa Website Tangerang adalah layanan profesional untuk membuat, mengembangkan, dan mengelola website bisnis lokal di Tangerang, termasuk company profile, toko online, landing page, dan web aplikasi custom.</p>', 1, 1, '2025-12-30 18:54:34', '2026-02-17 20:20:43'),
(2, 'Mengapa bisnis di Tangerang membutuhkan website?', '<p>\r\n<h3 data-start=\"718\" data-end=\"781\"></h3></p><p data-start=\"544\" data-end=\"716\">Website membantu bisnis di Tangerang tampil profesional, meningkatkan kredibilitas, dan memudahkan pelanggan lokal menemukan usaha Anda melalui Google dan pencarian online.</p>', 1, 2, '2025-12-30 18:54:34', '2026-02-17 20:21:44'),
(3, 'Jenis website apa saja yang bisa dibuat di Tangerang?', '<p data-start=\"782\" data-end=\"963\">Kami menyediakan pembuatan <span data-start=\"809\" data-end=\"892\" style=\"\">website company profile, website toko online (e-commerce), landing page promosi</span>, dan <span data-start=\"898\" data-end=\"921\" style=\"\">web aplikasi custom</span> untuk bisnis di Tangerang dan sekitarnya.</p>\r\n<h3 data-start=\"965\" data-end=\"1031\"></h3>', 1, 3, '2025-12-30 18:54:34', '2026-02-17 20:22:26'),
(4, 'Apakah website yang dibuat SEO friendly untuk Tangerang?', '<p>\r\n<h3 data-start=\"1219\" data-end=\"1276\"></h3></p><p data-start=\"1032\" data-end=\"1217\">Ya. Setiap website dioptimalkan dengan SEO lokal Tangerang, struktur meta tag, heading, dan konten yang mendukung peringkat Google untuk kata kunci seperti “jasa website Tangerang”.</p>', 1, 4, '2025-12-30 18:54:34', '2026-02-17 20:23:03'),
(5, 'Apakah website bisa diakses melalui smartphone?', '<p data-start=\"1277\" data-end=\"1454\">Semua website yang kami buat <strong data-start=\"1306\" data-end=\"1327\">mobile responsive</strong>, sehingga pengunjung dari Tangerang dan sekitarnya dapat mengakses website dengan mudah di smartphone, tablet, maupun desktop.</p>\r\n<h3 data-start=\"1456\" data-end=\"1516\"></h3>', 1, 5, '2025-12-30 18:54:34', '2026-02-17 20:23:23'),
(6, 'Berapa lama proses pembuatan website di Tangerang?', '<p>\r\n<h3 data-start=\"1663\" data-end=\"1728\"></h3></p><p data-start=\"1517\" data-end=\"1661\">Durasi tergantung jenis website dan fitur. Rata-rata 2–6 minggu untuk website company profile atau toko online standar bagi klien Tangerang.</p>', 1, 6, '2026-02-17 20:23:58', '2026-02-17 20:23:58'),
(7, 'Apakah ada layanan maintenance setelah website selesai?', '<p>\r\n<h3 data-start=\"1871\" data-end=\"1942\"></h3></p><p data-start=\"1729\" data-end=\"1869\">Ya. Kami menyediakan IT support &amp; website maintenance Tangerang, termasuk update konten, keamanan, perbaikan bug, dan optimasi performa.</p>', 1, 7, '2026-02-17 20:24:23', '2026-02-17 20:24:23'),
(8, 'Apakah website bisa custom sesuai kebutuhan bisnis Tangerang?', '<p>\r\n<h3 data-start=\"2109\" data-end=\"2165\"></h3></p><p data-start=\"1943\" data-end=\"2107\">Tentu. Kami menyediakan website custom Tangerang, mulai dari desain UI/UX, fitur e-commerce, sistem booking, hingga integrasi API sesuai kebutuhan bisnis lokal.</p>', 1, 8, '2026-02-17 20:24:48', '2026-02-17 20:24:48'),
(9, 'Berapa biaya jasa pembuatan website Tangerang?', '<p>\r\n<h3 data-start=\"2341\" data-end=\"2408\"></h3></p><p data-start=\"2166\" data-end=\"2339\">Harga <span data-start=\"2172\" data-end=\"2201\" style=\"\">transparan dan kompetitif</span>, disesuaikan dengan jenis website, jumlah halaman, fitur tambahan, dan kompleksitas sistem yang dibutuhkan oleh bisnis Anda di Tangerang.</p>', 1, 9, '2026-02-17 20:25:13', '2026-02-17 20:25:13'),
(10, 'Bagaimana cara memulai menggunakan jasa website Tangerang?', '<p data-start=\"2409\" data-end=\"2610\">Hubungi kami untuk <span data-start=\"2428\" data-end=\"2449\" style=\"\">konsultasi gratis</span>. Tim profesional kami akan mengevaluasi kebutuhan bisnis Anda dan membuat solusi website terbaik agar bisnis Anda lebih mudah ditemukan di Tangerang dan Google.</p>', 1, 10, '2026-02-17 20:25:38', '2026-02-17 20:25:38');
